<?php
$title='Manajemen Pengguna';$page='users';$pdo=Database::connection();$flash=get_flash();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$role=$_POST['role']??'siswa';if(!in_array($role,['admin','guru','siswa'],true))$role='siswa';
$name=trim($_POST['name']??'');$username=trim($_POST['username']??'');$class=trim($_POST['class_name']??'');
if($name&&$username){if($id){$q=$pdo->prepare('UPDATE users SET name=?,username=?,role=?,class_name=? WHERE id=?');$q->execute([$name,$username,$role,$class?:null,$id]);}else{$pass=password_hash(($_POST['password'] ?? '') ?: 'Siswa123!',PASSWORD_DEFAULT);$q=$pdo->prepare('INSERT INTO users(name,username,role,class_name,password) VALUES(?,?,?,?,?)');$q->execute([$name,$username,$role,$class?:null,$pass]);}flash('success','Data pengguna tersimpan.');}redirect('users');}
if(isset($_GET['delete'])){$q=$pdo->prepare('DELETE FROM users WHERE id=? AND role<>"admin"');$q->execute([(int)$_GET['delete']]);flash('success','Pengguna dihapus jika tidak terkait data penting.');redirect('users');}
$rows=$pdo->query('SELECT id,name,username,role,class_name,is_active FROM users ORDER BY role,name')->fetchAll();$classes=$pdo->query('SELECT name FROM classes ORDER BY name')->fetchAll();
require __DIR__.'/../_dashboard_start.php'; ?>
<div class="page-heading"><div><span class="eyebrow">ADMINISTRASI AKUN</span><h1>Manajemen Pengguna</h1><p>Kelola akun administrator, guru, dan siswa.</p></div></div>
<?php if($flash): ?><div class="alert <?= e($flash['type']) ?>"><?= e($flash['message']) ?></div><?php endif; ?>
<div class="dashboard-grid two"><section class="panel"><div class="panel-head"><h3>Tambah Pengguna</h3></div><form method="post" class="form-grid"><?= csrf_field() ?><label>Nama lengkap<input name="name" required></label><label>Username / NIP / NISN<input name="username" required></label><label>Role<select name="role"><option value="siswa">Siswa</option><option value="guru">Guru</option><option value="admin">Admin</option></select></label><label>Kelas (khusus siswa)<select name="class_name"><option value="">Pilih kelas</option><?php foreach($classes as $c): ?><option><?= e($c['name']) ?></option><?php endforeach; ?></select></label><label>Password awal<input name="password" placeholder="Kosongkan: Siswa123!"></label><button class="btn btn-primary">Simpan Pengguna</button></form></section>
<section class="panel"><div class="panel-head"><h3>Petunjuk akun</h3></div><p class="muted">Username mengikuti NIP/NIK untuk guru dan admin, serta NISN untuk siswa. Password awal dibuat oleh administrator dan harus diganti sebelum penggunaan produksi.</p><div class="notice"><i class="fa-solid fa-shield-halved"></i> Gunakan password unik dan jangan membagikan kredensial melalui grup publik.</div></section></div>
<section class="panel"><div class="panel-head"><h3>Daftar Pengguna <span class="count"><?= count($rows) ?></span></h3><input class="table-search" id="tableSearch" placeholder="Cari nama atau username..."></div><div class="table-wrap"><table id="dataTable"><thead><tr><th>Nama</th><th>Username</th><th>Role</th><th>Kelas</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['name']) ?></td><td><?= e($r['username']) ?></td><td><span class="badge"><?= e(ucfirst($r['role'])) ?></span></td><td><?= e($r['class_name']??'—') ?></td><td><?= $r['is_active']?'<span class="badge success">Aktif</span>':'<span class="badge danger">Nonaktif</span>' ?></td><td><?php if($r['role']!=='admin'): ?><a class="btn-icon danger-text" onclick="return confirm('Hapus pengguna ini?')" href="<?= e(url('users?delete='.$r['id'])) ?>"><i class="fa-solid fa-trash"></i></a><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php require __DIR__.'/../_dashboard_end.php'; ?>